    let w = innerWidth;
    addEventListener("resize", () => { if ((w <= 640) !== (innerWidth <= 640)) cfg.forEach(([q, sel, n, nm]) => document.querySelectorAll(q).forEach((box) => clamp(box, sel, n, nm))); w = innerWidth; });
