      return trimA([id, sp.t ? Math.round(sp.t / 864e5) - 19000 : 0, sp.s || 0, r4(sp.now), sp.m === "gap" ? 1 : 0, r4(sp.c), hi, sp.memo || "", sp.goal ? 1 : 0, sp.mig ? 1 : 0, sp.sn && r.s !== sp.s ? sp.sn : ""]);
