    g.fillStyle = "rgba(255,255,255,.07)"; g.strokeStyle = "rgba(255,255,255,.28)"; g.lineWidth = 1.6 / S; g.lineJoin = "round";
    D.map.gu.forEach(([, d]) => { const p = new Path2D(d); g.fill(p); g.stroke(p); });
