  const saveC = () => lsW(CK, CONDS);
  const KINDS = [["", "전체 유형"], ["redev", "재개발"], ["rebuild", "재건축"], ["small", "가로·소규모"]];
  const STAGES = [[0, "단계 상관없음"], [4, "조합설립 이상"], [5, "사업시행 이상"], [6, "관리처분 이상"]];
  const kindOf = (r) => (/재건축/.test(r.k) ? "rebuild" : /가로|소규모/.test(r.k) ? "small" : "redev");
