window.ZP_T0 = { D: () => D, byId: (id) => byId[id], stage: (r) => stageName(r), name: (n) => shortName(n), cash: () => CASH, gap: () => gapMode(), inbox: () => INBOX, pins: () => PINS, ZF: () => ZF, esc: (s) => esc(s) };

