  try { new MutationObserver(() => { const h = $("sugg").hidden; $("q").setAttribute("aria-expanded", String(!h)); if (h) { $("q").removeAttribute("aria-activedescendant"); sIdx = -1; } }).observe($("sugg"), { attributes: true, attributeFilter: ["hidden"] }); } catch (e) {}
