    const gx = [...new Set([0, 5, 10, 15, 20, 25, 30, 35, 40].filter((y) => y <= YMAX - 2).concat(YMAX))]
      .map((y) => `<text x="${X(y)}" y="${H - 8}" class="sv-xl">${y ? y + "년" : "지금"}</text>`)
      .join("");
